"use strict";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
export default function LockCreateCancelButton({
  onCreateClick,
  onCancelClick,
  isDisabled = false,
  isProcessing = false,
  buttonText = "Create lock",
  showCancel = true
}) {
  const colors = useSporeColors();
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    background-color: ${(props) => {
    if (props.$disabled) return colors.surface2.val;
    return props.$lock ? colors.surface2Hovered.val : colors.accent1.val;
  }};
    color: ${(props) => {
    if (props.$disabled) return colors.neutral3.val;
    return props.$lock ? colors.neutral1.val : colors.surface1.val;
  }};
    border-radius: 12px;
    cursor: ${(props) => props.$disabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    flex-grow: 1;
    transition: all 0.2s ease;
    opacity: ${(props) => props.$disabled ? 0.5 : 1};
    &:hover {
      opacity: ${(props) => props.$disabled ? 0.5 : 0.7};
    }
  `;
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      {showCancel && <Button $lock onClick={onCancelClick} $disabled={isProcessing}>
          <Text variant="buttonLabel3" color={"inherit"}>
            Cancel
          </Text>
        </Button>}
      <Button onClick={onCreateClick} $disabled={isDisabled || isProcessing}>
        <Text variant="buttonLabel3" color={"inherit"}>
          {isProcessing ? "Processing..." : buttonText}
        </Text>
      </Button>
    </Flex>;
}
